INSERT INTO `tabel_temuan` (`kode_temuan`, `kode_lha`, `parent_temuan`, `kriteria`, `sebab`, `tanggal_input`) VALUES ('T-003-E', 'LHP-BPK-2025-03', 'T-003', 'Regulasi yang belum direvisi dengan terbentuknya Kemenko Pangan', '- Sekretaris Kementerian Koordinator Bidang Pangan belum sepenuhnya optimal  dalam:\n\n1. Melaksanakan sinkronisasi dan evaluasi atas regulasi yang terkait dengan penyelenggaraan  pertanian dan pangan yang sudah ada; dan\n2. mengidentifikasi seluruh kebutuhan regulasi yang terkait dengan pelaksanaan tugas pokok dan fungsi Kemenko Pangan\n\n- Pembentukan Lembaga Pemerintah yang melaksanakan tugas pemerintahan di bidang pangan yang cukup lama dari waktu penetapan UU Pangan', '2026-07-13 03:18:36.479129');
INSERT INTO `tabel_temuan` (`kode_temuan`, `kode_lha`, `parent_temuan`, `kriteria`, `sebab`, `tanggal_input`) VALUES ('T-003-F', 'LHP-BPK-2025-03', 'T-003', 'Regulasi Pelaksanaan Teknis Kegiatan di Lingkungan Kemenko Pangan belum ditetapkan oleh Menteri Koordinator Bidang Pangan', '- Sekretaris Kementerian Koordinator Bidang Pangan belum sepenuhnya optimal  dalam:\n\n1. Melaksanakan sinkronisasi dan evaluasi atas regulasi yang terkait dengan penyelenggaraan  pertanian dan pangan yang sudah ada; dan\n2. mengidentifikasi seluruh kebutuhan regulasi yang terkait dengan pelaksanaan tugas pokok dan fungsi Kemenko Pangan\n\n- Pembentukan Lembaga Pemerintah yang melaksanakan tugas pemerintahan di bidang pangan yang cukup lama dari waktu penetapan UU Pangan', '2026-07-13 03:18:36.479134');
INSERT INTO `tabel_temuan` (`kode_temuan`, `kode_lha`, `parent_temuan`, `kriteria`, `sebab`, `tanggal_input`) VALUES ('T-004', 'LHP-BPK-2025-04', NULL, 'Kelembagaan Pangan Masyarakat Belum Bersinergi untuk Mendukung Swasembada Pangan Berkelanjutan dan Program Ketahanan Pangan Nasional di Mulai dari Tingkat Desa\nHasil pemeriksaan menunjukkan permasalahan yang perlu diperbaiki dan menjadiperhatian sebagai berikut :', NULL, '2026-07-13 03:18:36.479135');
INSERT INTO `tabel_temuan` (`kode_temuan`, `kode_lha`, `parent_temuan`, `kriteria`, `sebab`, `tanggal_input`) VALUES ('T-004-A', 'LHP-BPK-2025-04', 'T-004', 'Pembentukan KDKMP Belum Sepenuhnya Optimal Mendukung Swasembada Pangan Berkelanjutan', '1. Ketua Satuan Tugas Provinsi tidak optimal melaporkan perkembangan KDKMP kepada Ketua Satuan Tugas Nasional secara berkala\n\n2. Menteri Koordinator Bidang Pangan belum sepenuhnya optimal dalam mengkoordinasikan pelaksanaan pemantauan, evaluasi dan pelaporan secara terpadu dengan Kementerian/Lembaga dan Pemerintah sebagaimana Instruksi Presiden Nomor 9 Tahun 2025 tentang Percepatan Pembentukan Koperasi Desa/Kelurahan Merah Putih\n\n3. Menteri PPN/Kepala Bappenas belum optimal dalam melakukan Koordinasi dalam tata kelola manajemen resiko Pembangunan Nasional dalam KDKMP sebagaimana Instruksi Presiden Nomor 9 tahun 2025\n\n4. Kepala Badab Pangan Nasional belum optimal mendukung Tata Niaga Pangan KDKMP  sebagaimana Instruksi Presiden Nomor 9 tahun 2025 dan Kepala Badan Pangan Nasional sebagai Ketua Tim Penyusun Proses Bisnis untuk Stabilisasi Pasokan dan Harga Pangan melalui Koperasi Desa/Kelurahan Merah Putih belum Optimal melaksanakan tugasnya sesuia dengan Keputusan Menteri Koordinator Bidang Pangan Selaku Ketua Satuan Tugas nasional Percepatan Pembentukan Koperasi Desa/Kelurahan Merah Putih Nomor 25/M.PANGAN/KEP/07/2025\n\n5. Kepala Badan Gizi Nasional belum mendukung tata niaga pangan KDKMP yang mewajibkan SPPG membeli kebutuhan bahan pokok melalui KDKMP sebagaimana Instruksi Presiden Nomor 9 Tahun 2025\n\n6. Kepala Badan Pengaturan Badan Usaha Milik negara belum optimal mengoordinasikan BUMN dalam penguatan ekosistem sektor pangan, pertanian, kesehatan, logistik dan Modal Kerja KDKMP sebagaimana Instruksi Presiden Nomor 9  Tahun 2025\n\n7. Menteri Sosial belum menyusun kebijakan penerima manfaat bantuan sosial  menjadi anggota KDKMP dan penyaluran bantuan sosial melalui KDKMP sebagaimana Instruksi presiden Nomor 9 tahun 2025\n\n8. Menteri Keuangan belum optimal menyusun dan melaksanakan kebijakan pendanaan untuk mendukung pembangunan fisik dan kelengkapan KDMP sesuai dengan kemampuan dan peruntukan Dana Desa sesuai ketentuan Peraturan Perundang-undangan  sebagaimana Instruksi presiden Nomor 9 Tahun 2025\n\n9. Menteri Desa dan Pembangunan Daerah Tertinggal  belum optimal melaksanakan strategi dan kebijakan pembangunan desa dan penggunaan Dana Desa untuk pembangunan fisik dan kelengkapan KDMP sebagaimana Instruksi Presinen Nomor 9 Tahun 2025\n\n10. Menteri Koperasi Belum Optimal menyusun Bisnis Model KDKMP sebagaimana Instruksi Presiden Nomor 9 tahun 2025 dan kurang cermat dalam melakukan  perikatan dengan Direktur Utama PT. APN (Persero); dan\n\n11. Kemenko Pangan belum merumuskan dan menetapkan kebijakan dalam rangka sinkronisasi dan koordinasi untuk mengintegrasikan berbagai lembaga pendukung Ketahanan Pangan yang terdapat de desa dalam rangka mendukung Swasembada Pangan yang berkelanjutan dan Program Ketahanan Pangan Nasional', '2026-07-13 03:18:36.479135');
INSERT INTO `tabel_temuan` (`kode_temuan`, `kode_lha`, `parent_temuan`, `kriteria`, `sebab`, `tanggal_input`) VALUES ('T-004-B', 'LHP-BPK-2025-04', 'T-004', 'Kemenko Pangan Belum Merumuskan Kebijakan Sinkronisasi Kelembagaan Pangan Masyarakat untuk Mendukung Swasembada Pangan berkelanjutan dan Program Ketahanan Pangan nasional di mulai dari Desa', '1. Ketua Satuan Tugas Provinsi tidak optimal melaporkan perkembangan KDKMP kepada Ketua Satuan Tugas Nasional secara berkala\n\n2. Menteri Koordinator Bidang Pangan belum sepenuhnya optimal dalam mengkoordinasikan pelaksanaan pemantauan, evaluasi dan pelaporan secara terpadu dengan Kementerian/Lembaga dan Pemerintah sebagaimana Instruksi Presiden Nomor 9 Tahun 2025 tentang Percepatan Pembentukan Koperasi Desa/Kelurahan Merah Putih\n\n3. Menteri PPN/Kepala Bappenas belum optimal dalam melakukan Koordinasi dalam tata kelola manajemen resiko Pembangunan Nasional dalam KDKMP sebagaimana Instruksi Presiden Nomor 9 tahun 2025\n\n4. Kepala Badab Pangan Nasional belum optimal mendukung Tata Niaga Pangan KDKMP  sebagaimana Instruksi Presiden Nomor 9 tahun 2025 dan Kepala Badan Pangan Nasional sebagai Ketua Tim Penyusun Proses Bisnis untuk Stabilisasi Pasokan dan Harga Pangan melalui Koperasi Desa/Kelurahan Merah Putih belum Optimal melaksanakan tugasnya sesuia dengan Keputusan Menteri Koordinator Bidang Pangan Selaku Ketua Satuan Tugas nasional Percepatan Pembentukan Koperasi Desa/Kelurahan Merah Putih Nomor 25/M.PANGAN/KEP/07/2025\n\n5. Kepala Badan Gizi Nasional belum mendukung tata niaga pangan KDKMP yang mewajibkan SPPG membeli kebutuhan bahan pokok melalui KDKMP sebagaimana Instruksi Presiden Nomor 9 Tahun 2025\n\n6. Kepala Badan Pengaturan Badan Usaha Milik negara belum optimal mengoordinasikan BUMN dalam penguatan ekosistem sektor pangan, pertanian, kesehatan, logistik dan Modal Kerja KDKMP sebagaimana Instruksi Presiden Nomor 9  Tahun 2025\n\n7. Menteri Sosial belum menyusun kebijakan penerima manfaat bantuan sosial  menjadi anggota KDKMP dan penyaluran bantuan sosial melalui KDKMP sebagaimana Instruksi presiden Nomor 9 tahun 2025\n\n8. Menteri Keuangan belum optimal menyusun dan melaksanakan kebijakan pendanaan untuk mendukung pembangunan fisik dan kelengkapan KDMP sesuai dengan kemampuan dan peruntukan Dana Desa sesuai ketentuan Peraturan Perundang-undangan  sebagaimana Instruksi presiden Nomor 9 Tahun 2025\n\n9. Menteri Desa dan Pembangunan Daerah Tertinggal  belum optimal melaksanakan strategi dan kebijakan pembangunan desa dan penggunaan Dana Desa untuk pembangunan fisik dan kelengkapan KDMP sebagaimana Instruksi Presinen Nomor 9 Tahun 2025\n\n10. Menteri Koperasi Belum Optimal menyusun Bisnis Model KDKMP sebagaimana Instruksi Presiden Nomor 9 tahun 2025 dan kurang cermat dalam melakukan  perikatan dengan Direktur Utama PT. APN (Persero); dan\n\n11. Kemenko Pangan belum merumuskan dan menetapkan kebijakan dalam rangka sinkronisasi dan koordinasi untuk mengintegrasikan berbagai lembaga pendukung Ketahanan Pangan yang terdapat de desa dalam rangka mendukung Swasembada Pangan yang berkelanjutan dan Program Ketahanan Pangan Nasional', '2026-07-13 03:18:36.479135');
