INSERT INTO `tabel_rekomendasi` (`kode_rekomendasi`, `kode_temuan`, `rekomendasi`, `pic`, `rencana_aksi`, `jadwal_pelaksanaan`, `status`, `nilai_temuan`, `nilai_realisasi`, `selisih`, `tanggal_input`) VALUES ('R-001-A', 'T-001-A', 'Melakukan Kajian dan Evaluasi terhadap Struktur Organisasi kemenko Pangan yang belum sepenuhnya mendukung pelaksanaan tugas pokok dan fungsinya serta digunakan sebagai bahan rancangan perubahan struktur Organisasi Kemenko pangan.', 'Biro SDMO', 'Rapat internal kemenko bidang pangan untuk melakukan kajian dan evaluasi terhadap Struktur Organisasi Kemenko Pangan yang belum sepenuhnya mendukung pelaksanaan tugas pokok dan fungsinya serta digunakan sebagai bahan rancangan perubahan Struktur Organisasi Kemenko Pangan', 'Semester I 2026', 'PROSES', 0, 0, 0, '2026-07-13 03:18:36.518432');
INSERT INTO `tabel_rekomendasi` (`kode_rekomendasi`, `kode_temuan`, `rekomendasi`, `pic`, `rencana_aksi`, `jadwal_pelaksanaan`, `status`, `nilai_temuan`, `nilai_realisasi`, `selisih`, `tanggal_input`) VALUES ('R-001-B', 'T-001-B', 'Merumuskan dan menetapkan kebijakan dalam rangka sinkronisasi dan koordinasi kebijakan terkait sistem Informasi Pangan yang belum mampu menghasilkan informasi yang akurat, mutakhir, dan terpadu antar kementerian/ Lembaga untuk menyusun perencanaan pangan nasional dan neraca pangan nasional dan daerah', 'Biro MKDI', 'Rapat sinkronisasi dan koordinasi terkait evaluasi pemanfaatan sistem informasi pangan yang sudah dibangun oleh BAPANAS untuk menghasilkan informasi yang akurat, mutakhir, dan terpadu antar kementerian/lembaga mendukung penyusunan perencanaan pangan nasional dan neraca pangan nasional dan daerah.', 'Semester I 2026', 'PROSES', 0, 0, 0, '2026-07-13 03:18:36.518436');
INSERT INTO `tabel_rekomendasi` (`kode_rekomendasi`, `kode_temuan`, `rekomendasi`, `pic`, `rencana_aksi`, `jadwal_pelaksanaan`, `status`, `nilai_temuan`, `nilai_realisasi`, `selisih`, `tanggal_input`) VALUES ('R-002-A-Staf Ahli Bid Konektifitas', 'T-002-A1', 'Mengkoordinasikan BAPANAS untuk melengkapi unsur RPN yang belum memuat strategi dan kebijakan perencanaan pada rancangan RPN Tahun 2025-2029', 'Staf Ahli Bid. Konektifitas', 'Rapat Koordinasi dengan Bapanas dan Kementerian/Lembaga terkait untuk menyempurnakan RPN guna memuat strategi dan kebijakan perencanaan pada Rancangan RPN Tahun 2025-2029', 'Semester I 2026', 'PENDING', 0, 0, 0, '2026-07-13 03:18:36.518436');
