-- ====================================================================
-- DATABASE DUMP e-TLHP KEMENKO BIDANG PANGAN (MYSQL / MARIADB)
-- Kompatibel dengan phpMyAdmin Hostinger
-- ====================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- 1. Tabel Master LHA
DROP TABLE IF EXISTS `master_lha`;
CREATE TABLE `master_lha` (
  `kode_lha` VARCHAR(50) NOT NULL,
  `sumber_audit` VARCHAR(50) NOT NULL,
  `jenis_audit` VARCHAR(50) NOT NULL DEFAULT 'Audit Kinerja',
  `tahun` INT NOT NULL,
  `status_laporan` VARCHAR(50) NOT NULL DEFAULT 'Dalam Pemantauan',
  `tanggal_input` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`kode_lha`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Tabel Temuan
DROP TABLE IF EXISTS `tabel_temuan`;
CREATE TABLE `tabel_temuan` (
  `kode_temuan` VARCHAR(50) NOT NULL,
  `kode_lha` VARCHAR(50) NOT NULL,
  `parent_temuan` VARCHAR(50) DEFAULT NULL,
  `kondisi` TEXT DEFAULT NULL,
  `kriteria` TEXT NOT NULL,
  `sebab` TEXT DEFAULT NULL,
  `akibat` TEXT DEFAULT NULL,
  `tanggal_input` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`kode_temuan`),
  KEY `idx_temuan_lha` (`kode_lha`),
  KEY `idx_temuan_parent` (`parent_temuan`),
  CONSTRAINT `fk_temuan_lha` FOREIGN KEY (`kode_lha`) REFERENCES `master_lha` (`kode_lha`) ON DELETE CASCADE,
  CONSTRAINT `fk_temuan_parent` FOREIGN KEY (`parent_temuan`) REFERENCES `tabel_temuan` (`kode_temuan`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Tabel Rekomendasi
DROP TABLE IF EXISTS `tabel_rekomendasi`;
CREATE TABLE `tabel_rekomendasi` (
  `kode_rekomendasi` VARCHAR(50) NOT NULL,
  `kode_temuan` VARCHAR(50) NOT NULL,
  `rekomendasi` TEXT NOT NULL,
  `pic` VARCHAR(255) NOT NULL,
  `rencana_aksi` TEXT DEFAULT NULL,
  `jadwal_pelaksanaan` VARCHAR(100) DEFAULT NULL,
  `status` VARCHAR(20) NOT NULL DEFAULT 'PENDING',
  `nilai_temuan` DECIMAL(15,2) DEFAULT '0.00',
  `nilai_realisasi` DECIMAL(15,2) DEFAULT '0.00',
  `selisih` DECIMAL(15,2) DEFAULT '0.00',
  `tanggal_input` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`kode_rekomendasi`),
  KEY `idx_rekomendasi_temuan` (`kode_temuan`),
  KEY `idx_rekomendasi_pic` (`pic`),
  CONSTRAINT `fk_rekomendasi_temuan` FOREIGN KEY (`kode_temuan`) REFERENCES `tabel_temuan` (`kode_temuan`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. Tabel Bukti Tindak Lanjut
DROP TABLE IF EXISTS `tabel_bukti_tindak_lanjut`;
CREATE TABLE `tabel_bukti_tindak_lanjut` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `kode_rekomendasi` VARCHAR(50) NOT NULL,
  `output_aktual` TEXT NOT NULL,
  `file_bukti_path` VARCHAR(255) DEFAULT NULL,
  `ntpn` VARCHAR(50) DEFAULT NULL,
  `status_review` VARCHAR(20) NOT NULL DEFAULT 'PENDING',
  `catatan_auditor` TEXT DEFAULT NULL,
  `tanggal_mulai` DATETIME DEFAULT NULL,
  `tanggal_selesai` DATETIME DEFAULT NULL,
  `tanggal_submit` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `tanggal_review` DATETIME DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_bukti_rekomendasi` (`kode_rekomendasi`),
  CONSTRAINT `fk_bukti_rekomendasi` FOREIGN KEY (`kode_rekomendasi`) REFERENCES `tabel_rekomendasi` (`kode_rekomendasi`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 5. Tabel BATL
DROP TABLE IF EXISTS `tabel_batl`;
CREATE TABLE `tabel_batl` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `kode_lha` VARCHAR(50) NOT NULL,
  `nomor_batl` VARCHAR(100) NOT NULL,
  `tanggal_penerbitan` DATETIME NOT NULL,
  `file_path` VARCHAR(255) NOT NULL,
  `tanda_tangan_auditor` TINYINT(1) DEFAULT 0,
  `tanda_tangan_satker` TINYINT(1) DEFAULT 0,
  `tanggal_input` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_nomor_batl` (`nomor_batl`),
  KEY `idx_batl_lha` (`kode_lha`),
  CONSTRAINT `fk_batl_lha` FOREIGN KEY (`kode_lha`) REFERENCES `master_lha` (`kode_lha`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 6. Tabel User
DROP TABLE IF EXISTS `tabel_user`;
CREATE TABLE `tabel_user` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `username` VARCHAR(50) NOT NULL,
  `password` VARCHAR(100) NOT NULL,
  `role` VARCHAR(20) NOT NULL,
  `pic` VARCHAR(100) DEFAULT NULL,
  `tanggal_input` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

